create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',role text not null default 'responsavel' check(role in('admin','responsavel','aluno')),phone text,created_at timestamptz not null default now());
create table if not exists public.students(id uuid primary key default gen_random_uuid(),full_name text not null,birth_date date,age_group text not null check(age_group in('6-10','11-15')),guardian_id uuid references public.profiles(id) on delete set null,guardian_name text,status text not null default 'ativo' check(status in('ativo','inativo','pendente')),created_at timestamptz not null default now());
create table if not exists public.enrollment_requests(id uuid primary key default gen_random_uuid(),student_name text not null,birth_date date not null,guardian_name text not null,guardian_email text not null,phone text not null,age_group text not null check(age_group in('6-10','11-15')),notes text,status text not null default 'pending' check(status in('pending','contacted','approved','rejected')),created_at timestamptz not null default now());
create table if not exists public.attendance(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.students(id) on delete cascade,session_date date not null,present boolean not null default false,notes text,created_by uuid references public.profiles(id),created_at timestamptz not null default now(),unique(student_id,session_date));
create table if not exists public.payments(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.students(id) on delete cascade,amount numeric(10,2) not null check(amount>=0),due_date date,paid_at timestamptz,status text not null default 'pending' check(status in('pending','paid','overdue','cancelled')),payment_method text,reference text,created_at timestamptz not null default now());
create table if not exists public.resources(id uuid primary key default gen_random_uuid(),title text not null,url text not null,type text not null default 'pdf' check(type in('pdf','video','image','document')),description text,published boolean not null default true,created_by uuid references public.profiles(id),created_at timestamptz not null default now());
create table if not exists public.events(id uuid primary key default gen_random_uuid(),title text not null,event_date timestamptz not null,description text,created_by uuid references public.profiles(id),created_at timestamptz not null default now());
create table if not exists public.gallery(id uuid primary key default gen_random_uuid(),title text not null,image_url text not null,alt_text text,published boolean not null default true,created_by uuid references public.profiles(id),created_at timestamptz not null default now());
create table if not exists public.messages(id uuid primary key default gen_random_uuid(),sender_id uuid not null references public.profiles(id) on delete cascade,recipient_id uuid references public.profiles(id) on delete cascade,body text not null check(length(body) between 1 and 5000),read_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.suggestions(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id) on delete set null,name text,message text not null check(length(message) between 1 and 5000),status text not null default 'new' check(status in('new','reviewing','answered','closed')),created_at timestamptz not null default now());
create table if not exists public.contact_messages(id uuid primary key default gen_random_uuid(),name text not null,email text not null,message text not null check(length(message) between 1 and 5000),created_at timestamptz not null default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin'); $$;
create or replace function public.is_guardian(sid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.students where id=sid and guardian_id=auth.uid()); $$;
alter table public.profiles enable row level security;alter table public.students enable row level security;alter table public.enrollment_requests enable row level security;alter table public.attendance enable row level security;alter table public.payments enable row level security;alter table public.resources enable row level security;alter table public.events enable row level security;alter table public.gallery enable row level security;alter table public.messages enable row level security;alter table public.suggestions enable row level security;alter table public.contact_messages enable row level security;
create policy "profile read own admin" on public.profiles for select to authenticated using(id=auth.uid() or public.is_admin());
create policy "profile update own admin" on public.profiles for update to authenticated using(id=auth.uid() or public.is_admin()) with check(id=auth.uid() or public.is_admin());
create policy "profile insert own" on public.profiles for insert to authenticated with check(id=auth.uid() or public.is_admin());
create policy "admin students" on public.students for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "guardian linked students" on public.students for select to authenticated using(guardian_id=auth.uid());
create policy "public enrollment submit" on public.enrollment_requests for insert to anon,authenticated with check(status='pending');
create policy "admin enrollment" on public.enrollment_requests for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "admin attendance" on public.attendance for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "guardian attendance" on public.attendance for select to authenticated using(public.is_guardian(student_id));
create policy "admin payments" on public.payments for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "guardian payments" on public.payments for select to authenticated using(public.is_guardian(student_id));
create policy "public resources" on public.resources for select to anon,authenticated using(published or public.is_admin());
create policy "admin resources" on public.resources for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "read events" on public.events for select to anon,authenticated using(true);
create policy "admin events" on public.events for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "public gallery" on public.gallery for select to anon,authenticated using(published or public.is_admin());
create policy "admin gallery" on public.gallery for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "read messages" on public.messages for select to authenticated using(sender_id=auth.uid() or recipient_id=auth.uid() or public.is_admin());
create policy "send messages" on public.messages for insert to authenticated with check(sender_id=auth.uid());
create policy "update messages" on public.messages for update to authenticated using(recipient_id=auth.uid() or public.is_admin()) with check(recipient_id=auth.uid() or public.is_admin());
create policy "submit suggestions" on public.suggestions for insert to authenticated with check(user_id=auth.uid());
create policy "admin suggestions" on public.suggestions for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "public contact" on public.contact_messages for insert to anon,authenticated with check(true);
create policy "admin contact" on public.contact_messages for select to authenticated using(public.is_admin());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,role) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),'responsavel') on conflict(id) do nothing;return new;end;$$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
-- Após criar sua conta proprietária, encontre seu UUID em Authentication > Users e execute:
-- update public.profiles set role='admin' where id='<UUID-DA-SUA-CONTA>';
